import{_ as t,o,c as a,a2 as n}from"./chunks/framework.CTx8wfac.js";const h=JSON.parse('{"title":"Advanced Concepts","description":"","frontmatter":{},"headers":[],"relativePath":"guide/advanced-concepts.md","filePath":"guide/advanced-concepts.md"}'),r={name:"guide/advanced-concepts.md"};function s(d,e,c,i,l,p){return o(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="advanced-concepts" tabindex="-1">Advanced Concepts <a class="header-anchor" href="#advanced-concepts" aria-label="Permalink to &quot;Advanced Concepts&quot;">​</a></h1><p>BananaJS ships a <strong>wide</strong> enterprise surface—auth, OpenAPI, plugins, cache, metrics, multi-tenancy, ABAC, security decorators—not a “basic” framework with a few extras. This page maps the major <strong>implemented</strong> options; for signatures, use <a href="/banana-universe/api/">TypeDoc</a>.</p><h2 id="bananaappoptions" tabindex="-1"><code>BananaAppOptions</code> <a class="header-anchor" href="#bananaappoptions" aria-label="Permalink to &quot;`BananaAppOptions`&quot;">​</a></h2><p><code>BananaApp</code> is constructed as:</p><div class="language-typescript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">typescript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">new</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> BananaApp</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(controllers, options)</span></span>\n<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// or</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">await</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> BananaApp.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">create</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(controllers, options)</span></span></code></pre></div><p>The second argument is the <strong><code>BananaAppOptions</code></strong> object (<code>packages/bananajs/src/lib/Core/App.ts</code>). Highlights:</p><table tabindex="0"><thead><tr><th>Area</th><th>Options (illustrative)</th></tr></thead><tbody><tr><td><strong>HTTP</strong></td><td><code>middlewares</code> — extra Express handlers before routes</td></tr><tr><td><strong>Security</strong></td><td><code>security.helmet</code>, <code>security.cors</code> — defaults on; can disable or pass config</td></tr><tr><td><strong>Request ID</strong></td><td><code>requestId</code> — default <code>true</code></td></tr><tr><td><strong>Logging</strong></td><td><code>logger</code> — <code>Logger</code> instance or <code>false</code></td></tr><tr><td><strong>DI</strong></td><td><code>container</code> — <strong>awilix</strong> container for <code>@Injectable</code> resolution</td></tr><tr><td><strong>Shutdown</strong></td><td><code>gracefulShutdown</code> — SIGINT/SIGTERM hooks</td></tr><tr><td><strong>Auth</strong></td><td><code>auth.guard</code> — <strong><code>AuthGuard</code></strong> for <code>@Auth</code> / <code>@Roles</code> / <code>@Public</code></td></tr><tr><td><strong>Swagger</strong></td><td><code>swagger.enabled</code>, <code>path</code>, <code>title</code>, <code>version</code>, ... — OpenAPI JSON + UI</td></tr><tr><td><strong>Rate limit</strong></td><td><code>rateLimit</code> — global rate limiting (optional peer)</td></tr><tr><td><strong>Health</strong></td><td><code>health.enabled</code>, <code>path</code>, <code>checks</code> — <strong><code>GET /health</code></strong></td></tr><tr><td><strong>Plugins</strong></td><td><code>plugins</code> — <strong><code>BananaPlugin[]</code></strong>; use <strong><code>BananaApp.create</code></strong> for async registration</td></tr><tr><td><strong>Cache</strong></td><td><code>cache.store</code> — memory (default) or custom <strong><code>CacheStore</code></strong></td></tr><tr><td><strong>DevTools</strong></td><td><code>devTools</code> — <code>GET /_banana/routes</code> in non-production</td></tr><tr><td><strong>Metrics</strong></td><td><code>metrics.enabled</code>, <code>path</code> — Prometheus (optional peer)</td></tr><tr><td><strong>ABAC</strong></td><td><code>abac.guard</code> — <strong><code>AbacGuard</code></strong> for <code>@Can</code></td></tr><tr><td><strong>Multi-tenancy</strong></td><td><code>tenant</code> — tenant resolution and <strong><code>TenantContext</code></strong></td></tr><tr><td><strong>Performance</strong></td><td><code>lazyControllers</code> — defer controller instantiation to first use</td></tr></tbody></table><p>Exact field types and defaults are in the <strong><a href="/banana-universe/reference/bananaapp-options.html">BananaAppOptions interface</a></strong> and TypeDoc.</p><h2 id="authentication-decorators" tabindex="-1">Authentication decorators <a class="header-anchor" href="#authentication-decorators" aria-label="Permalink to &quot;Authentication decorators&quot;">​</a></h2><ul><li><strong><code>@Auth()</code></strong> — class or method; requires a configured <strong><code>auth.guard</code></strong></li><li><strong><code>@Roles(&#39;a&#39;, &#39;b&#39;)</code></strong> — method-level role checks</li><li><strong><code>@Public()</code></strong> — opt out of auth on a route when the class is protected</li></ul><p>Guards are <strong>interfaces</strong> — no JWT or session baked in.</p><h2 id="openapi" tabindex="-1">OpenAPI <a class="header-anchor" href="#openapi" aria-label="Permalink to &quot;OpenAPI&quot;">​</a></h2><p>Decorators such as <strong><code>@ApiTags</code></strong>, <strong><code>@ApiOperation</code></strong>, <strong><code>@ApiBody</code></strong>, <strong><code>@ApiResponseDoc</code></strong> feed the schema extractor. The spec is exposed (typically <strong><code>/api-docs.json</code></strong>) with a documentation UI when Swagger options are enabled.</p><h2 id="caching" tabindex="-1">Caching <a class="header-anchor" href="#caching" aria-label="Permalink to &quot;Caching&quot;">​</a></h2><p><strong><code>@Cache</code></strong> and <strong><code>@CacheEvict</code></strong> use the <strong><code>CacheManager</code></strong> singleton. Memory store is built-in; plug in Redis or another backend via <strong><code>CacheStore</code></strong>.</p><h2 id="file-uploads" tabindex="-1">File uploads <a class="header-anchor" href="#file-uploads" aria-label="Permalink to &quot;File uploads&quot;">​</a></h2><p><strong><code>@Upload</code></strong> integrates <strong>multer</strong> (optional peer) for multipart uploads.</p><h2 id="rate-limiting" tabindex="-1">Rate limiting <a class="header-anchor" href="#rate-limiting" aria-label="Permalink to &quot;Rate limiting&quot;">​</a></h2><p><strong><code>@RateLimit</code></strong> (express-rate-limit) and <strong><code>@Throttle</code></strong> (per-user / IP throttling) address different use cases.</p><h2 id="security-helpers" tabindex="-1">Security helpers <a class="header-anchor" href="#security-helpers" aria-label="Permalink to &quot;Security helpers&quot;">​</a></h2><ul><li><strong><code>@Sanitize</code></strong> — HTML strip on string fields (sanitize-html, optional peer)</li><li><strong><code>@Can(&#39;action&#39;, &#39;resource&#39;)</code></strong> — ABAC with <strong><code>abac.guard</code></strong></li></ul><h2 id="multi-tenancy" tabindex="-1">Multi-tenancy <a class="header-anchor" href="#multi-tenancy" aria-label="Permalink to &quot;Multi-tenancy&quot;">​</a></h2><p><strong><code>@Tenant</code></strong>, <strong><code>TenantContext</code></strong>, <strong><code>getTenantId</code></strong>, <strong><code>runWithTenant</code></strong>, <strong><code>createTenantMiddleware</code></strong> — tenant id from header or JWT claim; cache keys can be namespaced. See repo <strong><code>docs/MULTI-TENANCY.md</code></strong> for deep patterns.</p><h2 id="framework-adapter" tabindex="-1">Framework adapter <a class="header-anchor" href="#framework-adapter" aria-label="Permalink to &quot;Framework adapter&quot;">​</a></h2><p><strong><code>FrameworkAdapter</code></strong> and <strong><code>RouteDefinition</code></strong> support future non-Express HTTP stacks. <strong><code>@banana-universe/adapter-fastify</code></strong> is an experimental stub.</p><h2 id="static-helpers" tabindex="-1">Static helpers <a class="header-anchor" href="#static-helpers" aria-label="Permalink to &quot;Static helpers&quot;">​</a></h2><ul><li><strong><code>BananaRouter</code></strong> — mount generated routes into an existing Express app (incremental migration)</li><li><strong><code>BananaApp.getRouteTable()</code></strong> — introspection for tooling</li></ul><h2 id="websocket" tabindex="-1">WebSocket <a class="header-anchor" href="#websocket" aria-label="Permalink to &quot;WebSocket&quot;">​</a></h2><p>Real-time features use <strong><code>@banana-universe/plugin-websocket</code></strong> (see <a href="/banana-universe/plugins/websocket.html">WebSocket plugin</a>). It is a <strong><code>BananaPlugin</code></strong> and requires <strong><code>attachToServer(httpServer)</code></strong> after <code>listen()</code>.</p><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ul><li><a href="/banana-universe/plugins/overview.html">Plugins overview</a></li><li><a href="/banana-universe/guide/layered-architecture.html">Layered architecture &amp; DDD</a></li><li><a href="/banana-universe/recipes/">Recipes</a></li></ul>',31)])])}const u=t(r,[["render",s]]);export{h as __pageData,u as default};
